settings.custom_liquid:
{% comment %}
  מיסטרי בוקס - product info block (title + price + group price + included + team steps + trust)
  Paste into: product page → Add block → Custom Liquid (right under the price).
  Then hide the theme's Title, Price and Description blocks so nothing shows twice,
  and hide the Koala widget.
  ✏️ Edit the numbers / links below.
{% endcomment %}

{%- assign gp_min = 5 -%}
{%- assign gp_new_price = 79 -%}
{%- assign gp_new_was = 99 -%}
{%- assign gp_retro_price = 89 -%}
{%- assign gp_retro_was = 109 -%}
{%- assign link_sizes = 'https://hashofet.com/pages/טבלת-מידות' -%}
{%- assign link_insta = 'https://instagram.com/hanut.hashofet' -%}
{%- assign link_whatsapp = 'https://wa.me/972515310498' -%}

{%- assign cur = product.selected_or_first_available_variant -%}

{%- assign gp_in_cart = 0 -%}
{%- for item in cart.items -%}
  {%- if item.product.handle == product.handle -%}
    {%- assign gp_in_cart = gp_in_cart | plus: item.quantity -%}
  {%- endif -%}
{%- endfor -%}

<style>
  .hpi {
    --ink: #121212;
    --muted: #666258;
    --sand: #efece3;
    --line: #e2ded3;
    --navy: #14234f;
    --maroon: #7d1d2c;
    --green: #1a9c52;
    direction: rtl;
    color: var(--ink);
    font-family: inherit;
    margin: 16px 0 8px;
  }
  .hpi a { color: inherit; }

  /* ---------- breathing room between gallery and info (RTL fix) ---------- */
  @media screen and (min-width: 750px) {
    .product__info-wrapper {
      padding-left: 0 !important;
      padding-right: 5rem !important;
    }
  }
  @media screen and (min-width: 990px) {
    .product__info-wrapper { padding-right: 7rem !important; }
  }

  /* ---------- title + price ---------- */
  .hpi__head { margin: 0 0 18px; }
  .hpi__title {
    font-size: 38px; font-weight: 900; line-height: 1.1;
    letter-spacing: -0.02em; margin: 0 0 10px;
  }
  .hpi__pricerow { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
  .hpi__price { font-size: 24px; font-weight: 800; font-variant-numeric: tabular-nums; }
  .hpi__compare { font-size: 16px; color: var(--muted); text-decoration: line-through; }
  .hpi__compare:empty { display: none; }
  .hpi__per {
    font-size: 13px; font-weight: 700; color: var(--muted);
    background: var(--sand); border-radius: 100px; padding: 3px 12px;
  }

  /* ---------- group price (hero) ---------- */
  .gp {
    background: var(--sand);
    border: 1px solid var(--line);
    border-radius: 20px;
    padding: 20px;
  }
  .gp__title { font-size: 17px; font-weight: 800; margin: 0 0 14px; line-height: 1.3; }
  .gp__cards { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  .gp__card {
    background: #fff;
    border-radius: 14px;
    padding: 14px 16px 14px 12px;
    border-right: 5px solid var(--kit);
    display: flex; flex-direction: column; gap: 2px;
  }
  .gp__card--new { --kit: var(--navy); }
  .gp__card--retro { --kit: var(--maroon); }
  .gp__name { font-size: 14px; font-weight: 700; color: var(--kit); }
  .gp__row { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
  .gp__price { font-size: 34px; font-weight: 900; line-height: 1.05; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  .gp__price small { font-size: 17px; font-weight: 800; margin-right: 2px; }
  .gp__was { font-size: 14px; color: var(--muted); text-decoration: line-through; }
  .gp__save { font-size: 13px; font-weight: 700; color: var(--green); }
  .gp__track {
    display: flex; align-items: center; gap: 14px;
    margin-top: 16px; padding-top: 14px;
    border-top: 1px dashed #d5d0c3;
  }
  .gp__slots { display: flex; gap: 4px; flex-shrink: 0; }
  .gp__slot { width: 26px; height: 24px; color: #cfc9ba; transition: color .25s ease, transform .25s ease; }
  .gp__slot svg { width: 100%; height: 100%; display: block; }
  .gp__slot.is-on { color: var(--ink); }
  .gp.is-unlocked .gp__slot.is-on { color: var(--green); }
  .gp__slot.is-pop { transform: scale(1.18); }
  .gp__status { font-size: 14px; font-weight: 600; line-height: 1.4; margin: 0; }
  .gp__status b { font-weight: 800; }
  .gp.is-unlocked .gp__status { color: var(--green); }

  /* ---------- sections ---------- */
  .hpi__sec { margin-top: 26px; }
  .hpi__h { font-size: 16px; font-weight: 800; margin: 0 0 12px; }

  .hpi__incl { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
  .hpi__incl li { display: flex; gap: 12px; align-items: flex-start; font-size: 15px; line-height: 1.5; }
  .hpi__incl b { font-weight: 800; }
  .hpi__ic {
    flex-shrink: 0; width: 30px; height: 30px; border-radius: 9px;
    background: var(--sand); color: var(--ink);
    display: flex; align-items: center; justify-content: center;
  }
  .hpi__ic svg { width: 17px; height: 17px; }
  .hpi__incl a { font-weight: 700; text-underline-offset: 3px; }
  .hpi__note { font-size: 13px; color: var(--muted); }

  .hpi__steps { list-style: none; margin: 0; padding: 0; counter-reset: s; position: relative; }
  .hpi__steps li {
    counter-increment: s; position: relative;
    padding: 0 44px 16px 0; font-size: 15px; line-height: 1.5;
  }
  .hpi__steps li:last-child { padding-bottom: 0; }
  .hpi__steps li::before {
    content: counter(s);
    position: absolute; right: 0; top: -2px;
    width: 30px; height: 30px; border-radius: 50%;
    background: var(--ink); color: #fff;
    font-weight: 800; font-size: 14px;
    display: flex; align-items: center; justify-content: center;
  }
  .hpi__steps li:not(:last-child)::after {
    content: ""; position: absolute; right: 14px; top: 30px; bottom: 2px;
    width: 2px; background: var(--line);
  }
  .hpi__steps li:last-child::before { background: var(--green); }
  .hpi__steps b { font-weight: 800; }

  .hpi__trust {
    margin-top: 26px;
    display: grid; grid-template-columns: repeat(3, 1fr);
    border: 1px solid var(--line); border-radius: 16px; overflow: hidden;
  }
  .hpi__t { padding: 14px 10px; text-align: center; font-size: 13px; line-height: 1.35; }
  .hpi__t + .hpi__t { border-right: 1px solid var(--line); }
  .hpi__t svg { width: 22px; height: 22px; display: block; margin: 0 auto 6px; }
  .hpi__t b { display: block; font-size: 13.5px; font-weight: 800; }
  .hpi__t span { color: var(--muted); }
  a.hpi__t { text-decoration: none; }
  a.hpi__t:hover b { text-decoration: underline; text-underline-offset: 3px; }

  .hpi__bulk { margin: 14px 0 0; font-size: 14px; color: var(--muted); text-align: center; }
  .hpi__bulk a { color: var(--green); font-weight: 800; text-underline-offset: 3px; }

  .hpi a:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }

  @media (max-width: 480px) {
    .hpi__title { font-size: 32px; }
    .gp { padding: 16px; }
    .gp__price { font-size: 30px; }
    .gp__track { flex-direction: column; align-items: flex-start; gap: 8px; }
    .hpi__t { padding: 12px 6px; font-size: 12px; }
    .hpi__t b { font-size: 12.5px; }
  }
  @media (prefers-reduced-motion: reduce) { .gp__slot { transition: none; } }
</style>

<div class="hpi" id="hpi-{{ section.id }}">

  <!-- title + price -->
  <div class="hpi__head">
    <h1 class="hpi__title">{{ product.title }}</h1>
    <div class="hpi__pricerow">
      <span class="hpi__price" data-price>{{ cur.price | divided_by: 100 }}₪</span>
      <span class="hpi__compare" data-compare>{% if cur.compare_at_price > cur.price %}{{ cur.compare_at_price | divided_by: 100 }}₪{% endif %}</span>
      <span class="hpi__per">לחולצה בודדת</span>
    </div>
  </div>

  <!-- group price -->
  <div class="gp" id="gp-{{ section.id }}" data-min="{{ gp_min }}" data-handle="{{ product.handle }}" data-count="{{ gp_in_cart }}">
    <p class="gp__title">מזמינים {{ gp_min }} חולצות ומעלה? המחיר יורד לכל חולצה</p>
    <div class="gp__cards">
      <div class="gp__card gp__card--new">
        <span class="gp__name">עונת 26/27</span>
        <div class="gp__row"><span class="gp__price">{{ gp_new_price }}<small>₪</small></span><span class="gp__was">{{ gp_new_was }}₪</span></div>
        <span class="gp__save">חוסכים {{ gp_new_was | minus: gp_new_price }}₪</span>
      </div>
      <div class="gp__card gp__card--retro">
        <span class="gp__name">רטרו</span>
        <div class="gp__row"><span class="gp__price">{{ gp_retro_price }}<small>₪</small></span><span class="gp__was">{{ gp_retro_was }}₪</span></div>
        <span class="gp__save">חוסכים {{ gp_retro_was | minus: gp_retro_price }}₪</span>
      </div>
    </div>
    <div class="gp__track">
      <div class="gp__slots" aria-hidden="true">
        {%- for i in (1..gp_min) -%}
          <span class="gp__slot"><svg viewBox="0 0 26 24"><path fill="currentColor" d="M8.5 1.5 3 4 .8 9.6l4 1.7L6.3 8.6V22.5h13.4V8.6l1.5 2.7 4-1.7L23 4l-5.5-2.5c-.6 1.8-2.4 3-4.5 3s-3.9-1.2-4.5-3z"/></svg></span>
        {%- endfor -%}
      </div>
      <p class="gp__status" aria-live="polite"></p>
    </div>
  </div>

  <!-- included -->
  <div class="hpi__sec">
    <p class="hpi__h">כלול בכל חולצה</p>
    <ul class="hpi__incl">
      <li>
        <span class="hpi__ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></span>
        <span><b>שם, מספר ופאץ'</b> בלי תוספת תשלום</span>
      </li>
      <li>
        <span class="hpi__ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21.3 8.7 15.3 2.7a1 1 0 0 0-1.4 0L2.7 13.9a1 1 0 0 0 0 1.4l6 6a1 1 0 0 0 1.4 0L21.3 10.1a1 1 0 0 0 0-1.4z"/><path d="m7.5 10.5 2 2M10.5 7.5l2 2M13.5 4.5l2 2M4.5 13.5l2 2"/></svg></span>
        <span>מידות לפי גובה, לא לפי גיל. <a href="{{ link_sizes }}">לטבלת המידות</a></span>
      </li>
      <li>
        <span class="hpi__ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/></svg></span>
        <span class="hpi__note">בגרסת אוהד יכולות להגיע גם חולצות ממונדיאל 2026</span>
      </li>
      <li>
        <span class="hpi__ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 7h12l-1 14H7z"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/></svg></span>
        <span class="hpi__note">החולצות נשלחות בשקית, לא בקופסה. תמונת הקופסה להמחשה בלבד</span>
      </li>
    </ul>
  </div>

  <!-- team steps -->
  <div class="hpi__sec">
    <p class="hpi__h">מזמינים לכל הצוות</p>
    <ol class="hpi__steps">
      <li>בחרו מידה, גרסה והעדפות לחבר הראשון והוסיפו לעגלה</li>
      <li>חזרו על זה לכל חבר</li>
      <li>מ־{{ gp_min }} חולצות <b>המחיר יורד אוטומטית</b></li>
    </ol>
  </div>

  <!-- trust -->
  <div class="hpi__trust">
    <div class="hpi__t">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/></svg>
      <b>PayPal או העברה בנקאית</b>
    </div>
    <div class="hpi__t">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M1 3h15v13H1zM16 8h4l3 3v5h-7z"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
      <b>משלוח חינם</b><span>10-14 ימי עסקים</span>
    </div>
    <a class="hpi__t" href="{{ link_insta }}" target="_blank" rel="noopener">
      <svg viewBox="0 0 24 24"><path fill="#1D9BF0" d="M12 1l2.6 2.2 3.4-.4.9 3.3 3 1.7-1.3 3.2 1.3 3.2-3 1.7-.9 3.3-3.4-.4L12 23l-2.6-2.2-3.4.4-.9-3.3-3-1.7L3.4 13 2.1 9.8l3-1.7.9-3.3 3.4.4z"/><path d="M8 12.2l2.7 2.6L16.2 9" stroke="#fff" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <b>מאומתים באינסטגרם</b><span>לחצו לבדיקה</span>
    </a>
  </div>

  <p class="hpi__bulk">יש שאלות? <a href="{{ link_whatsapp }}" target="_blank" rel="noopener">דברו איתנו בוואטסאפ</a></p>
</div>

<script type="application/json" id="hpi-variants-{{ section.id }}">
  [{%- for v in product.variants -%}{"id":{{ v.id }},"p":{{ v.price }},"c":{{ v.compare_at_price | default: 0 }}}{% unless forloop.last %},{% endunless %}{%- endfor -%}]
</script>
<script>
(function () {
  var root = document.getElementById('hpi-{{ section.id }}');
  var data = document.getElementById('hpi-variants-{{ section.id }}');
  if (!root || !data) return;
  var variants = JSON.parse(data.textContent);
  var elP = root.querySelector('[data-price]'), elC = root.querySelector('[data-compare]');
  function fmt(c) { var n = c / 100; return (n % 1 ? n.toFixed(2) : n) + '₪'; }
  function currentId() {
    var inp = document.querySelector('form[action*="/cart/add"] [name="id"]');
    var fromUrl = new URLSearchParams(location.search).get('variant');
    return (inp && inp.value) || fromUrl;
  }
  function update() {
    var id = String(currentId() || '');
    var v = variants.find(function (x) { return String(x.id) === id; });
    if (!v) return;
    elP.textContent = fmt(v.p);
    elC.textContent = v.c > v.p ? fmt(v.c) : '';
  }
  document.addEventListener('change', function () { setTimeout(update, 60); });
  document.addEventListener('click', function (e) { if (e.target.closest('variant-selects, variant-radios, fieldset, .product-form__input')) setTimeout(update, 80); });
  window.addEventListener('popstate', update);
})();
</script>
<script>
(function () {
  var box = document.getElementById('gp-{{ section.id }}');
  if (!box || box.dataset.ready) return;
  box.dataset.ready = '1';
  var min = parseInt(box.dataset.min, 10);
  var handle = box.dataset.handle;
  var slots = box.querySelectorAll('.gp__slot');
  var status = box.querySelector('.gp__status');
  var last = -1;

  function render(count) {
    slots.forEach(function (s, i) {
      var on = i < Math.min(count, min);
      if (on && !s.classList.contains('is-on') && last >= 0) {
        s.classList.add('is-pop');
        setTimeout(function () { s.classList.remove('is-pop'); }, 250);
      }
      s.classList.toggle('is-on', on);
    });
    var left = min - count;
    box.classList.toggle('is-unlocked', left <= 0);
    if (left <= 0) {
      status.innerHTML = '<b>' + count + ' חולצות בעגלה.</b> המחיר המוזל פעיל';
    } else if (count === 0) {
      status.innerHTML = 'מ־' + min + ' חולצות המחיר יורד אוטומטית בעגלה';
    } else {
      var have = count === 1 ? 'חולצה אחת בעגלה' : count + ' חולצות בעגלה';
      var need = left === 1 ? 'עוד חולצה אחת' : 'עוד ' + left + ' חולצות';
      status.innerHTML = '<b>' + have + '.</b> ' + need + ' והמחיר יורד';
    }
    last = count;
  }

  function refresh() {
    fetch('/cart.js', { headers: { 'Accept': 'application/json' } })
      .then(function (r) { return r.json(); })
      .then(function (cart) {
        var n = 0;
        cart.items.forEach(function (it) { if (it.handle === handle) n += it.quantity; });
        render(n);
      })
      .catch(function () {});
  }

  render(parseInt(box.dataset.count, 10) || 0);

  var origFetch = window.fetch;
  window.fetch = function () {
    var url = arguments[0] && (arguments[0].url || arguments[0]);
    var p = origFetch.apply(this, arguments);
    if (typeof url === 'string' && /\/cart\/(add|change|update|clear)/.test(url)) {
      p.then(function () { setTimeout(refresh, 150); });
    }
    return p;
  };
  document.addEventListener('visibilitychange', function () { if (!document.hidden) refresh(); });
})();
</script>

