<style>
  .qly {
    --ink: #121212; --muted: #6b6860; --line: #e2ded3; --sand: #efece3; --green: #1a9c52;
    direction: rtl; color: var(--ink); font-family: inherit; padding: 56px 0 60px;
  }
  .qly__wrap { max-width: 1120px; margin: 0 auto; padding: 0 20px; }
  .qly__title { margin: 0; text-align: center; font-size: clamp(28px, 3.6vw, 42px); font-weight: 900; letter-spacing: -0.02em; line-height: 1.1; }
  .qly__sub { margin: 10px 0 0; text-align: center; color: var(--muted); font-size: 16px; }


  .qly__tog { display: flex; align-items: center; justify-content: center; gap: 14px; margin: 0 auto; background: none; border: 0; padding: 6px 10px; cursor: pointer; font: inherit; color: var(--ink); }
  .qly__tog .qly__title { margin: 0; }
  .qly__chev { width: 40px; height: 40px; border-radius: 50%; background: var(--sand); flex-shrink: 0; display: flex; align-items: center; justify-content: center; transition: transform .35s ease, background .2s; }
  .qly__chev svg { width: 20px; height: 20px; }
  .qly__tog:hover .qly__chev { background: #e4e0d4; }
  .qly__tog[aria-expanded="false"] .qly__chev { transform: rotate(180deg); }
  .qly__body { display: grid; grid-template-rows: 1fr; transition: grid-template-rows .45s ease; }
  .qly__body > div { overflow: hidden; }
  .qly__body.is-closed { grid-template-rows: 0fr; }
  @media (prefers-reduced-motion: reduce) { .qly__body, .qly__chev { transition: none; } }

  .qly__tabs {
    margin: 24px auto 26px; width: fit-content; display: flex; gap: 4px; padding: 5px;
    background: var(--sand); border-radius: 100px;
  }
  .qly__tab {
    border: 0; background: none; font: inherit; font-size: 16px; font-weight: 800; color: var(--muted);
    padding: 11px 26px; border-radius: 100px; cursor: pointer; transition: background .2s, color .2s, box-shadow .2s;
  }
  .qly__tab[aria-selected="true"] { background: #fff; color: var(--ink); box-shadow: 0 4px 12px rgba(0,0,0,.08); }
  .qly__tab:focus-visible, .qly button:focus-visible, .qly a:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; }

  .qly__panel { display: grid; grid-template-columns: 1.25fr 1fr; gap: 22px; align-items: start; }
  .qly__panel[hidden] { display: none; }

  .qly__main {
    position: relative; display: block; width: 100%; aspect-ratio: 1 / 1; padding: 0; border: 0; cursor: zoom-in;
    border-radius: 22px; overflow: hidden; background: #e9e6de;
  }
  .qly__main img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .5s ease; }
  .qly__main:hover img { transform: scale(1.03); }
  .qly__zoom {
    position: absolute; bottom: 14px; left: 14px; display: inline-flex; align-items: center; gap: 6px;
    background: rgba(18,18,18,.78); color: #fff; font-size: 13px; font-weight: 800; padding: 7px 12px; border-radius: 100px;
  }
  .qly__zoom svg { width: 15px; height: 15px; }
  .qly__real {
    position: absolute; top: 14px; right: 14px; background: #fff; color: var(--ink);
    font-size: 12.5px; font-weight: 800; padding: 6px 12px; border-radius: 100px; box-shadow: 0 4px 12px rgba(0,0,0,.12);
  }
  .qly__thumbs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 10px; }
  .qly__thumb { padding: 0; border: 2px solid transparent; border-radius: 14px; overflow: hidden; aspect-ratio: 1 / 1; cursor: pointer; background: #e9e6de; transition: border-color .2s, opacity .2s; opacity: .7; }
  .qly__thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
  .qly__thumb[aria-current="true"] { border-color: var(--ink); opacity: 1; }
  .qly__thumb:hover { opacity: 1; }

  .qly__card { background: #fff; border: 1px solid var(--line); border-radius: 22px; padding: 26px; }
  .qly__name { margin: 0; font-size: 28px; font-weight: 900; }
  .qly__tag { margin: 6px 0 20px; color: var(--muted); font-size: 16px; }
  .qly__specs { margin: 0; display: grid; gap: 0; }
  .qly__specs div { display: grid; grid-template-columns: 96px 1fr; gap: 12px; padding: 13px 0; border-top: 1px solid var(--line); font-size: 15px; line-height: 1.45; }
  .qly__specs dt { font-weight: 800; color: var(--muted); }
  .qly__specs dd { margin: 0; font-weight: 700; }
  .qly__note { margin: 16px 0 0; font-size: 13.5px; color: var(--muted); background: var(--sand); border-radius: 12px; padding: 10px 12px; line-height: 1.5; }
  .qly__note a { color: var(--ink); font-weight: 800; text-underline-offset: 3px; }
  .qly__cta { display: flex; justify-content: center; align-items: center; margin-top: 18px; height: 52px; border-radius: 14px; background: var(--ink); color: #fff; text-decoration: none; font-weight: 900; font-size: 16px; }

  /* lightbox */
  .qly__lb { border: 0; padding: 0; background: transparent; max-width: 100vw; max-height: 100vh; width: 100vw; height: 100vh; }
  .qly__lb::backdrop { background: rgba(10,10,10,.88); }
  .qly__lb[open] { display: flex; align-items: center; justify-content: center; }
  .qly__lb img { max-width: min(92vw, 1100px); max-height: 86vh; border-radius: 16px; display: block; }
  .qly__lbbtn {
    position: fixed; width: 48px; height: 48px; border-radius: 50%; border: 0; background: #fff; color: var(--ink);
    display: flex; align-items: center; justify-content: center; cursor: pointer; font-size: 22px; font-weight: 900;
  }
  .qly__lbbtn svg { width: 22px; height: 22px; }
  .qly__lbx { top: 18px; left: 18px; }
  .qly__lbp { top: 50%; right: 18px; transform: translateY(-50%); }
  .qly__lbn { top: 50%; left: 18px; transform: translateY(-50%); }

  @media (max-width: 860px) {
    .qly { padding: 42px 0 46px; }
    .qly__panel { grid-template-columns: 1fr; }
    .qly__tab { padding: 10px 18px; font-size: 15px; }
    .qly__name { font-size: 24px; }
    .qly__specs div { grid-template-columns: 84px 1fr; }
    .qly__lbp, .qly__lbn { top: auto; bottom: 22px; transform: none; }
    .qly__lbp { right: calc(50% - 60px); } .qly__lbn { left: calc(50% - 60px); }
  }
  @media (prefers-reduced-motion: reduce) { .qly__main img, .qly__tab, .qly__thumb { transition: none; } }
</style>

<section class="qly" id="qly-{{ section.id }}" aria-label="האיכות שלנו">
  <div class="qly__wrap">
    <button type="button" class="qly__tog" aria-expanded="{% if start_open %}true{% else %}false{% endif %}" aria-controls="qly-body-{{ section.id }}">
      <h2 class="qly__title">האיכות שלנו</h2><span class="qly__chev" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 15l6-6 6 6"/></svg></span>
    </button>
    <div class="qly__body{% unless start_open %} is-closed{% endunless %}" id="qly-body-{{ section.id }}"><div>
    <p class="qly__sub">צילומים אמיתיים, בלי פילטרים. ככה נראות החולצות שמגיעות אליכם</p>

    <div class="qly__tabs" role="tablist" aria-label="בחירת גרסה">
      <button class="qly__tab" role="tab" aria-selected="true" aria-controls="qly-p-{{ section.id }}" data-tab="0">גרסת שחקן</button>
      <button class="qly__tab" role="tab" aria-selected="false" aria-controls="qly-f-{{ section.id }}" data-tab="1">גרסת אוהד</button>
    </div>

    {%- for v in (1..2) -%}
      {%- if v == 1 -%}{%- assign imgs = player_list -%}{%- else -%}{%- assign imgs = fan_list -%}{%- endif -%}
      <div class="qly__panel" role="tabpanel" id="{% if v == 1 %}qly-p-{% else %}qly-f-{% endif %}{{ section.id }}" data-panel="{{ v | minus: 1 }}"{% if v == 2 %} hidden{% endif %}>
        <div>
          <button type="button" class="qly__main" data-open aria-label="הגדלת התמונה">
            <img src="{{ imgs[0] | strip }}&width=1100" alt="{% if v == 1 %}גרסת שחקן{% else %}גרסת אוהד{% endif %} - צילום אמיתי" loading="lazy" decoding="async" data-main>
            <span class="qly__real">צילום אמיתי</span>
            <span class="qly__zoom"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="M16.5 16.5 21 21M11 8v6M8 11h6"/></svg>הגדלה</span>
          </button>
          <div class="qly__thumbs">
            {%- for u in imgs -%}
              <button type="button" class="qly__thumb" data-i="{{ forloop.index0 }}" data-src="{{ u | strip }}&width=1100"{% if forloop.first %} aria-current="true"{% endif %} aria-label="תמונה {{ forloop.index }}">
                <img src="{{ u | strip }}&width=280" alt="" loading="lazy" decoding="async">
              </button>
            {%- endfor -%}
          </div>
        </div>

        <div class="qly__card">
          {%- if v == 1 -%}
            <h3 class="qly__name">גרסת שחקן</h3>
            <p class="qly__tag">כמו מה שהשחקנים לובשים על המגרש</p>
            <dl class="qly__specs">
              <div><dt>גזרה</dt><dd>צמודה לגוף</dd></div>
              <div><dt>בד</dt><dd>אלסטי וקל משקל, בנוי לביצועים</dd></div>
              <div><dt>מתאימה ל</dt><dd>משחקים, אימונים ולמי שאוהב גזרה צמודה</dd></div>
            </dl>
            <p class="qly__note">הגזרה צמודה, אז כדאי לבדוק מידה לפני שמזמינים. <a href="/pages/טבלת-מידות">לטבלת המידות</a></p>
          {%- else -%}
            <h3 class="qly__name">גרסת אוהד</h3>
            <p class="qly__tag">הקלאסיקה של היציע, נוחה ליומיום</p>
            <dl class="qly__specs">
              <div><dt>גזרה</dt><dd>רפויה ונוחה</dd></div>
              <div><dt>בד</dt><dd>נוח ואוורירי</dd></div>
              <div><dt>מתאימה ל</dt><dd>יומיום, יציע ומשחקים בטלוויזיה</dd></div>
            </dl>
            <p class="qly__note">מכנסיים שנמכרים בסט מגיעים בגרסת אוהד בלבד, גם אם החולצה בגרסת שחקן.</p>
          {%- endif -%}
          <a class="qly__cta" href="/collections/all">לכל החולצות</a>
        </div>
      </div>
    {%- endfor -%}
    </div></div>
  </div>

  <dialog class="qly__lb" aria-label="תמונה מוגדלת">
    <img alt="" data-lbimg>
    <button type="button" class="qly__lbbtn qly__lbx" data-close aria-label="סגירה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg></button>
    <button type="button" class="qly__lbbtn qly__lbp" data-prev aria-label="הקודמת"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg></button>
    <button type="button" class="qly__lbbtn qly__lbn" data-next aria-label="הבאה"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M15 18l-6-6 6-6"/></svg></button>
  </dialog>
</section>

<script>
(function () {
  var root = document.getElementById('qly-{{ section.id }}');
  if (!root || root.dataset.ready) return;
  root.dataset.ready = '1';
  var tabs = root.querySelectorAll('.qly__tab');
  var panels = root.querySelectorAll('.qly__panel');
  var lb = root.querySelector('.qly__lb'), lbImg = root.querySelector('[data-lbimg]');
  var cur = { panel: 0, i: 0 };
  var tog = root.querySelector('.qly__tog'), body = root.querySelector('.qly__body');
  tog.addEventListener('click', function () {
    var open = tog.getAttribute('aria-expanded') === 'true';
    tog.setAttribute('aria-expanded', open ? 'false' : 'true');
    body.classList.toggle('is-closed', open);
  });

  function srcs(p) { return Array.prototype.map.call(panels[p].querySelectorAll('.qly__thumb'), function (t) { return t.dataset.src; }); }
  function show(p, i) {
    var list = srcs(p); i = (i + list.length) % list.length; cur = { panel: p, i: i };
    panels[p].querySelector('[data-main]').src = list[i];
    panels[p].querySelectorAll('.qly__thumb').forEach(function (t, k) { t.setAttribute('aria-current', k === i ? 'true' : 'false'); });
    if (lb.open) lbImg.src = list[i];
  }
  tabs.forEach(function (t, k) {
    t.addEventListener('click', function () {
      tabs.forEach(function (x, j) { x.setAttribute('aria-selected', j === k ? 'true' : 'false'); });
      panels.forEach(function (pn, j) { pn.hidden = j !== k; });
      cur = { panel: k, i: 0 }; show(k, 0);
    });
  });
  panels.forEach(function (pn, p) {
    pn.querySelectorAll('.qly__thumb').forEach(function (t) { t.addEventListener('click', function () { show(p, +t.dataset.i); }); });
    pn.querySelector('[data-open]').addEventListener('click', function () {
      lbImg.src = srcs(p)[cur.panel === p ? cur.i : 0];
      if (lb.showModal) lb.showModal(); else lb.setAttribute('open', '');
    });
  });
  function close() { if (lb.close) lb.close(); else lb.removeAttribute('open'); }
  root.querySelector('[data-close]').addEventListener('click', close);
  root.querySelector('[data-prev]').addEventListener('click', function () { show(cur.panel, cur.i - 1); });
  root.querySelector('[data-next]').addEventListener('click', function () { show(cur.panel, cur.i + 1); });
  lb.addEventListener('click', function (e) { if (e.target === lb) close(); });
  lb.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowLeft') show(cur.panel, cur.i + 1);
    if (e.key === 'ArrowRight') show(cur.panel, cur.i - 1);
  });
})();
</script>
